def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    best = None

    # Find a long, uninterrupted row segment revealing the repeating sequence.
    for r in range(h):
        for start in range(w):
            for p in range(2, min(10, w - start) + 1):
                cycle = grid[r][start:start + p]
                if 0 in cycle or len(set(cycle)) != p:
                    continue

                length = p
                while start + length < w:
                    value = grid[r][start + length]
                    if value == 0 or value != grid[r][start + length - p]:
                        break
                    length += 1

                if length < max(3 * p, 12):
                    continue
                candidate = (length, -p, cycle[:])
                if best is None or candidate[:2] > best[:2]:
                    best = candidate

    if best is None:
        return [row[:] for row in grid]

    cycle = best[2]
    p = len(cycle)
    index = {value: i for i, value in enumerate(cycle)}
    out = [row[:] for row in grid]

    for r in range(h):
        votes = Counter(
            (index[value] - c) % p
            for c, value in enumerate(grid[r])
            if value in index
        )
        if not votes:
            continue

        phase, count = votes.most_common(1)[0]
        if count < 3 or count / sum(votes.values()) < 0.7:
            continue

        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = cycle[(c + phase) % p]

    return out
