def transform(grid):
    h, w = len(grid), len(grid[0])
    interior = [
        (r, c, grid[r][c])
        for r in range(3, h)
        for c in range(3, w)
        if grid[r][c] != 0
    ]

    # Find the repeating diagonal pattern: cells on each r+c residue
    # have the same color, cycling with some period.
    candidates = []
    for period in range(1, 11):
        counts = [dict() for _ in range(period)]
        for r, c, value in interior:
            residue = (r + c) % period
            counts[residue][value] = counts[residue].get(value, 0) + 1

        mapping = []
        correct = 0
        for bucket in counts:
            if bucket:
                color, n = max(bucket.items(), key=lambda item: item[1])
                mapping.append(color)
                correct += n
            else:
                mapping.append(None)

        accuracy = correct / max(1, len(interior))
        candidates.append((accuracy, period, mapping))

    best_accuracy = max(item[0] for item in candidates)
    # Prefer the simplest period when a larger period only repeats the same pattern.
    accuracy, period, mapping = min(
        (item for item in candidates if item[0] >= best_accuracy - 0.015),
        key=lambda item: item[1]
    )

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or (r == 2 and c < 2) or (r >= 3 and c < 2):
                out[r][c] = 1
            elif r == 2 or (r >= 3 and c == 2):
                out[r][c] = 4
            elif r >= 3 and c >= 3:
                color = mapping[(r + c) % period]
                if color is not None:
                    out[r][c] = color
    return out
